import { writeFileSync } from "node:fs";
import { createWeirdMock } from "/tmp/cxprobe/weird-mock.mjs";

const upstream = createWeirdMock();
const secret = "reprosecret";
const models = ["arr", "str", "num", "empty", "html"].map((s) => ({
  alias: "m-" + s,
  provider: "resp",
  upstreamModel: "up-" + s,
  efforts: ["high"],
  defaultEffort: "high",
  inputModalities: ["text"],
}));
writeFileSync(
  "/tmp/cxprobe/codextras-weird.json",
  JSON.stringify({
    gateway: { port: 0, pathPrefix: "/_codextras" },
    providers: [
      { id: "resp", type: "openai-responses", baseUrl: "http://127.0.0.1:" + upstream.port, apiKeyEnv: "CX_REPRO_KEY", quirks: {} },
    ],
    models,
  }, null, 2),
);
process.env.CX_REPRO_KEY = "sk-x";
process.env.CODEXTRAS_CONFIG = "/tmp/cxprobe/codextras-weird.json";
const { createServer } = await import("/Volumes/thinkplus/Code/coding-agent-stagnation/tasks/src-codextras-A-rutwork2/src/server.mjs");
const { loadConfig } = await import("/Volumes/thinkplus/Code/coding-agent-stagnation/tasks/src-codextras-A-rutwork2/src/config.mjs");
const server = createServer(loadConfig(), secret);
const base = "http://127.0.0.1:" + server.port + "/_codextras/" + secret;

const input = [{ type: "message", role: "user", content: [{ type: "input_text", text: "hi" }] }];
for (const s of ["arr", "str", "num", "empty", "html"]) {
  const res = await fetch(base + "/v1/responses", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ model: "m-" + s, input, stream: false }),
  });
  const text = await res.text();
  let parsed;
  try { parsed = JSON.parse(text); } catch { parsed = "<unparseable>"; }
  const isObj = parsed !== null && typeof parsed === "object" && !Array.isArray(parsed);
  console.log(s + ": status=" + res.status + " isJsonObject=" + isObj + " body=" + text.slice(0, 300));
}

server.stop(true);
upstream.stop(true);
delete process.env.CODEXTRAS_CONFIG;
process.exit(0);

