        return handleCompaction(request, payload, apiPath, rawBody);
      }
      if (apiPath === "/v1/responses") {
        return handleTurn(request, payload, apiPath, rawBody);
      }
      return json({ error: { message: "unknown route " + apiPath } }, 404);
    },
  });
